INSERT INTO knowledge_base (id, school_id, subject, grade, source, content, metadata) VALUES
  ('79000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', 'Mathematics', 'X', 'NCERT Chapter 8', 'Trigonometry is a branch of mathematics that studies relationships between side lengths and angles of triangles. The word trigonometry comes from the Greek words trigonon (triangle) and metron (measure).', '{"chapter": "Introduction to Trigonometry", "topic": "basics"}'),
  ('79000000-0000-0000-0000-000000000002', '11111111-1111-1111-1111-111111111111', 'Mathematics', 'X', 'NCERT Chapter 8', 'The six trigonometric ratios are sine, cosine, tangent, cosecant, secant, and cotangent. For a right-angled triangle with angle θ, sin θ = opposite/hypotenuse, cos θ = adjacent/hypotenuse, tan θ = opposite/adjacent.', '{"chapter": "Introduction to Trigonometry", "topic": "ratios"}'),
  ('79000000-0000-0000-0000-000000000003', '11111111-1111-1111-1111-111111111111', 'Physics', 'X', 'NCERT Chapter 9', 'Newton''s First Law of Motion states that an object at rest stays at rest and an object in motion stays in motion with the same speed and in the same direction unless acted upon by an unbalanced force. This law is also known as the law of inertia.', '{"chapter": "Laws of Motion", "topic": "newton_first_law"}'),
  ('79000000-0000-0000-0000-000000000004', '11111111-1111-1111-1111-111111111111', 'Physics', 'X', 'NCERT Chapter 9', 'Newton''s Second Law of Motion states that the acceleration of an object is directly proportional to the net force acting on it and inversely proportional to its mass. F = ma where F is force, m is mass, and a is acceleration.', '{"chapter": "Laws of Motion", "topic": "newton_second_law"}'),
  ('79000000-0000-0000-0000-000000000005', '11111111-1111-1111-1111-111111111111', 'Chemistry', 'X', 'NCERT Chapter 4', 'Chemical bonding is the attraction between atoms that allows the formation of chemical substances containing two or more atoms. The bond is caused by the electrostatic force of attraction between opposite charges.', '{"chapter": "Chemical Bonding", "topic": "introduction"}'),
  ('79000000-0000-0000-0000-000000000006', '11111111-1111-1111-1111-111111111111', 'English', 'X', 'Grammar Guide', 'An essay is a short piece of writing on a particular subject. It typically consists of an introduction, body paragraphs, and a conclusion. A good essay should have a clear thesis statement and supporting arguments.', '{"topic": "essay_writing", "skill": "writing"}'),
  ('79000000-0000-0000-0000-000000000007', '11111111-1111-1111-1111-111111111111', 'Computer Science', 'X', 'Python Guide', 'Python is a high-level, interpreted programming language known for its simplicity and readability. It supports multiple programming paradigms including procedural, object-oriented, and functional programming.', '{"topic": "python_introduction", "skill": "programming"}'),
  ('79000000-0000-0000-0000-000000000008', '11111111-1111-1111-1111-111111111111', 'Computer Science', 'X', 'Python Guide', 'A Python function is a block of organized, reusable code that is used to perform a single, related action. Functions provide better modularity for your application and a high degree of code reusing.', '{"topic": "python_functions", "skill": "programming"}')
